-- ============================================================================
-- Банк карточек Culture Fit Nudges (23 карточки) — PostgreSQL
-- Источник: ТЗ «Цифровая система онбординга КМГ», §5.2.2 / §9 (MVP: PostgreSQL nudge_cards).
-- Карточки утверждены ДУЧР и используются без изменений.
-- Применение: psql "$DATABASE_URL" -f db/nudge_cards.sql
-- ============================================================================

CREATE TABLE IF NOT EXISTS nudge_cards (
    day         SMALLINT     PRIMARY KEY CHECK (day BETWEEN 1 AND 23),
    theme       TEXT         NOT NULL,
    body        TEXT         NOT NULL,
    source_vnd  TEXT         NOT NULL,
    language    VARCHAR(2)   NOT NULL DEFAULT 'ru',
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

COMMENT ON TABLE  nudge_cards IS 'Банк из 23 ежедневных карточек Culture Fit (ТЗ §5.2.2)';
COMMENT ON COLUMN nudge_cards.day        IS 'День адаптации, 1..23 — день показа карточки';
COMMENT ON COLUMN nudge_cards.source_vnd IS 'Источник ВНД для цитирования (ПВТР / Кодекс этики / Комплаенс / Правила дресс-кода)';

ON CONFLICT (day) DO UPDATE
    SET theme = EXCLUDED.theme,
        body = EXCLUDED.body,
        source_vnd = EXCLUDED.source_vnd;
